@prefix dt: <https://geolabs.github.io/bblocks-data-types/def/> .
@prefix rim: <https://w3id.org/ogc/rim/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://geolabs.github.io/bblocks-data-types/def/data-type/never-added/v1> ;
            sh:resultMessage "A data type version must record its addition: a rim:hasAction of type rim:additionAction with a rim:proposer." ;
            sh:resultPath dt:hasVersionAction ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A data type version must record its addition: a rim:hasAction of type rim:additionAction with a rim:proposer." ;
                    sh:minCount 1 ;
                    sh:path dt:hasVersionAction ;
                    sh:qualifiedMinCount 1 ;
                    sh:qualifiedValueShape [ sh:class rim:RegisterAction ;
                            sh:property [ sh:hasValue rim:additionAction ;
                                    sh:path rim:actionType ],
                                [ sh:minCount 1 ;
                                    sh:path rim:proposer ] ] ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

